-- TomoModForever 1.3.0 release notes.

TomoMod_RegisterLocale("enUS", {
    ["mover_totems"] = "Totems",
    ["wn_130_totems"] = "New - Shamans: your totems are back with TomoMod's player frame (Blizzard's totem bar disappeared with the Blizzard player frame). Under the player frame: one spot per element, icon, sweep and time left, tooltip on hover, right click to dismiss a totem. Movable with /tmf move; size and empty spots in Frames > Player.",
    ["wn_130_omen"] = "Fixed - Missing buffs: druids no longer see \"Omen of Clarity\" as a missing buff. It is a passive spell on Forever and leaves no aura to check. Mark of the Wild is still checked.",
    ["wn_130_buffcombat"] = "Fixed - Missing buffs: a buff refreshed in combat no longer shows as missing once you leave combat.",
})

